import { execFileSync } from 'node:child_process';
import { readFileSync, appendFileSync } from 'node:fs';
const EXE = '/workspace/dataset/test11_executable';
function run(args){ try { return { out: execFileSync(EXE,args,{encoding:'utf8',maxBuffer:1<<28}), rc:0 }; } catch(e){ return { out:(e.stdout||'')+(e.stderr||''), rc:e.status, err:true }; } }
function mode(text,which){
  const args = which==='a'?['--a',text,'--b','','--c','']:which==='b'?['--a','','--b',text,'--c','']:['--a','','--b','','--c',text];
  const r=run(args); if(r.err) return 'ERR('+r.rc+'):'+r.out;
  const lead = which==='a'?0:which==='b'?1:2, trail = which==='a'?3:which==='b'?2:1;
  return r.out.slice(lead, r.out.length-trail);
}
const probes = JSON.parse(readFileSync(process.argv[2],'utf8'));
const outFile = process.argv[3];
for(const md of probes){
  const core=mode(md,'a'), tables=mode(md,'b'), extra=mode(md,'c');
  const line = JSON.stringify({md,core,tables,extra});
  if(outFile) appendFileSync(outFile, line+'\n');
  console.log('### MD    '+JSON.stringify(md));
  console.log('    core  '+JSON.stringify(core));
  console.log('    tabl  '+JSON.stringify(tables));
  console.log('    extra '+(extra===tables?'<same as tables>':JSON.stringify(extra)));
}
EOF
